import{_ as r,o as i,c as a,a3 as t}from"./chunks/framework.B5WAEDB7.js";const f=JSON.parse('{"title":"Practice records","description":"WheelOS rules for recording experiments and promoting guidance to verified evidence.","frontmatter":{"title":"Practice records","description":"WheelOS rules for recording experiments and promoting guidance to verified evidence.","status":"Repository fact","content_type":"practice","keywords":["practice records","evidence","reproducibility","validation"]},"headers":[],"relativePath":"en/practice/index.md","filePath":"en/practice/index.md","lastUpdated":1794216847000}'),o={name:"en/practice/index.md"};function c(n,e,d,s,l,p){return i(),a("div",null,[...e[0]||(e[0]=[t('<h1 id="practice-records" tabindex="-1">Practice records <a class="header-anchor" href="#practice-records" aria-label="Permalink to &quot;Practice records&quot;">​</a></h1><p>Practice records are the primary evidence source for this knowledge base. Only records with environment, procedure and results can move a topic from <code>Design guidance</code> to <code>Partially verified</code> or <code>Verified</code>. Formal records are indexed in the <a href="/en/evidence/">evidence index</a>.</p><h2 id="recording-rules" tabindex="-1">Recording rules <a class="header-anchor" href="#recording-rules" aria-label="Permalink to &quot;Recording rules&quot;">​</a></h2><ul><li>One record answers one falsifiable question.</li><li>A conclusion is bound to versions, hardware and data; avoid context-free &quot;supported&quot; claims.</li><li>Retain failed and unreproduced results.</li><li>Safety-related conclusions must state the test boundary; simulation cannot replace a safety case.</li></ul><p>Entry points: <a href="/en/practice/verified">Verified solutions</a> · <a href="/en/practice/hypotheses">Pending hypotheses</a> · <a href="/en/evidence/record-template">Evidence template</a></p>',5)])])}const h=r(o,[["render",c]]);export{f as __pageData,h as default};
